WITH lines AS (SELECT id, host, log_ts, level, status_code, attr_key, value FROM app_logs LATERAL VIEW EXPLODE(context) x AS attr_key, value) SELECT CASE WHEN status_code >= 410 THEN 'LARGE' ELSE 'SMALL' END AS status_code_tier, attr_key, SORT_ARRAY(COLLECT_SET(host)) AS host_list, BIT_OR(status_code) AS status_code_bit_or, STDDEV_SAMP(status_code) AS status_code_stddev, GROUPING_ID() AS grouping_level FROM lines GROUP BY GROUPING SETS ((CASE WHEN status_code >= 410 THEN 'LARGE' ELSE 'SMALL' END, attr_key), (CASE WHEN status_code >= 410 THEN 'LARGE' ELSE 'SMALL' END), ()) ORDER BY status_code_bit_or ASC;
